/// <summary>
/// Logic Block containing logic necessary to make a movement within the warehouse
/// </summary>
class MwmsLogicBlockMoveInvent extends MwmsLogicBlock implements TFMLogicBlockDataCollectionInterface, TFMLogicBlockPrePostDataModifyInterface
{

    InventJournalTable  inventJournalTable;
    InventJournalTrans  inventJournalTrans;
    InventDim           inventDimIssue;
    InventDim           inventDimReceipt;

}

Method.Source:
public void new()
{
    super();
    components.addComponent(new TFMLogicComponentDimensions());
    components.addComponent(new TFMLogicComponentQuantity());

    components.addComponent(new MwmsLogicComponentInventoryMovement());

}

public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMRegistrationCollectorList    fromWarehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(1, strLwr(extendedTypeStr(InventLocationId)), "@SYS25253", methodStr(TFMGetReferenceData,WarehouseList));
    // Warehouse to move from
    fromWarehouse.parmLinkedElement(2);
    fromWarehouse.parmLinkColumn(extendedTypeStr(InventLocationId));
    refConf.addCollector(fromWarehouse);
    // Warehouse to move to
    refConf.addCollector(TFMGetReferenceData::createDefaultWarehouseReferenceData(2,'To'+ strLwr(extendedTypeStr(InventLocationId)), "@SYS8519", methodStr(TFMGetReferenceData,WarehouseList)));
    // Item number text box
    refConf.addCollector(TFMGetReferenceData::defaultItemIdCollector(3));

    return refConf;
}

public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    TFMRegistrationCollectors               regCols = TFMRegistrationCollectors::Construct();


    return regCols;
}

/// <summary>
/// Method to set up tables to be used in the posting. Ensures that addons can be made, that can modify the data of the block before posting, when needed.
/// </summary>
public void preparePost()
{
    Qty                                 qty;
    TFMRequestItemAndDimensionElement   unplannedMoveRequest = request.convertToOtherRequestType(classStr(TFMRequestItemAndDimensionElement));
    ItemId                              itemId = unplannedMoveRequest.parmItemId();
    TFMLogicComponentDimensions         dimensionComponent = components.getComponent(classStr(TFMLogicComponentDimensions));

    inventDimIssue = dimensionComponent.getInventDim(request); // Component delivers data

    inventDimIssue.data(unplannedMoveRequest.parmInventDim());
    inventDimReceipt.data(unplannedMoveRequest.parmInventDim());

    inventDimIssue = InventDim::findOrCreate(unplannedMoveRequest.createFromInventDim(inventDimIssue));
    inventDimReceipt = InventDim::findOrCreate(unplannedMoveRequest.createToInventDim(inventDimReceipt));
    qty = unplannedMoveRequest.parmQuantity();

    inventJournalTable = MobPostHelper::inventJournalTransferHeaderCreate();
    inventJournalTrans = MobPostHelper::inventJournalTransferLineCreate(inventJournalTable, qty, itemId, inventDimIssue, inventDimReceipt);
}

public TFMPostResponseData post()
{
    TFMPostResponseData                 postElement = TFMPostResponseData::Construct();
    if (!inventJournalTable)
    {
        postElement.parmResponseText("@TaskletMobileWMS:Nomovementmade");
    }
    else
    {
        MobPostHelper::postInventJournalTransfer(inventJournalTable);
        inventJournalTable.reread();
        postElement.parmResponseText(strFmt("@TaskletMobileWMS:Moved1of2from3to4", inventJournalTrans.Qty, inventJournalTrans.ItemId, inventDimIssue.wMSLocationId, inventDimReceipt.wMSLocationId));
    }
    return postElement;
}
